import json
import math
from dataclasses import dataclass
from functools import lru_cache

import numpy as np
from scipy.linalg import eigh
from scipy.optimize import minimize
from scipy.special import gammainc, gammaln

from qiskit import QuantumCircuit, transpile
from qiskit.circuit import Parameter
from qiskit.circuit.library import PauliEvolutionGate
from qiskit.quantum_info import SparsePauliOp
from qiskit.synthesis import LieTrotter
from qiskit_aer import AerSimulator


@dataclass(frozen=True)
class _GaussianAO:
    center: tuple
    powers: tuple
    exponents: tuple
    weights: tuple
    label: str


@lru_cache(maxsize=8192)
def _hermite_coefficients(i, j, displacement, a, b):
    """Hermite expansion coefficients for two unnormalized 1D Gaussians."""
    p = a + b
    reduced_exponent = a * b / p

    @lru_cache(maxsize=None)
    def coefficient(ii, jj, t):
        if ii < 0 or jj < 0 or t < 0 or t > ii + jj:
            return 0.0
        if ii == 0 and jj == 0:
            return (
                math.exp(-reduced_exponent * displacement**2)
                if t == 0
                else 0.0
            )
        if jj == 0:
            return (
                coefficient(ii - 1, jj, t - 1) / (2.0 * p)
                - reduced_exponent * displacement / a
                * coefficient(ii - 1, jj, t)
                + (t + 1) * coefficient(ii - 1, jj, t + 1)
            )
        return (
            coefficient(ii, jj - 1, t - 1) / (2.0 * p)
            + reduced_exponent * displacement / b
            * coefficient(ii, jj - 1, t)
            + (t + 1) * coefficient(ii, jj - 1, t + 1)
        )

    return tuple(coefficient(i, j, t) for t in range(i + j + 1))


def _primitive_overlap(a, powers_a, center_a, b, powers_b, center_b):
    value = (math.pi / (a + b)) ** 1.5
    for axis in range(3):
        value *= _hermite_coefficients(
            powers_a[axis],
            powers_b[axis],
            center_a[axis] - center_b[axis],
            a,
            b,
        )[0]
    return value


def _primitive_kinetic(a, powers_a, center_a, b, powers_b, center_b):
    """Unnormalized kinetic integral; shifted powers retain original weights."""
    overlap = _primitive_overlap(
        a, powers_a, center_a, b, powers_b, center_b
    )
    value = b * (2 * sum(powers_b) + 3) * overlap

    for axis in range(3):
        raised = list(powers_b)
        raised[axis] += 2
        value -= 2.0 * b * b * _primitive_overlap(
            a, powers_a, center_a, b, tuple(raised), center_b
        )
        if powers_b[axis] >= 2:
            lowered = list(powers_b)
            lowered[axis] -= 2
            value -= (
                0.5
                * powers_b[axis]
                * (powers_b[axis] - 1)
                * _primitive_overlap(
                    a, powers_a, center_a, b, tuple(lowered), center_b
                )
            )
    return value


def _odd_double_factorial(n):
    value = 1
    for k in range(n, 0, -2):
        value *= k
    return value


def _primitive_normalization(exponent, powers):
    denominator = math.prod(
        _odd_double_factorial(2 * angular_momentum - 1)
        for angular_momentum in powers
    )
    return (
        (2.0 * exponent / math.pi) ** 0.75
        * (4.0 * exponent) ** (0.5 * sum(powers))
        / math.sqrt(denominator)
    )


def _make_ao(center, powers, exponents, coefficients, label):
    # STO-3G coefficients multiply normalized primitives. Renormalize the
    # contraction as well, eliminating rounding error in tabulated coefficients.
    center = tuple(float(x) for x in center)
    powers = tuple(powers)
    exponents = tuple(float(x) for x in exponents)
    weights = [
        coefficient * _primitive_normalization(exponent, powers)
        for exponent, coefficient in zip(exponents, coefficients)
    ]

    norm_squared = 0.0
    for a, wa in zip(exponents, weights):
        for b, wb in zip(exponents, weights):
            norm_squared += wa * wb * _primitive_overlap(
                a, powers, center, b, powers, center
            )
    if norm_squared <= 0.0:
        raise ArithmeticError("Invalid Gaussian contraction normalization.")

    scale = 1.0 / math.sqrt(norm_squared)
    return _GaussianAO(
        center, powers, exponents,
        tuple(scale * weight for weight in weights), label
    )


def _gaussian_pairs(ao_a, ao_b):
    """Store weighted Hermite expansions for all primitive pairs."""
    pairs = []
    for a, wa in zip(ao_a.exponents, ao_a.weights):
        for b, wb in zip(ao_b.exponents, ao_b.weights):
            p = a + b
            product_center = tuple(
                (a * ao_a.center[axis] + b * ao_b.center[axis]) / p
                for axis in range(3)
            )
            expansions = [
                _hermite_coefficients(
                    ao_a.powers[axis],
                    ao_b.powers[axis],
                    ao_a.center[axis] - ao_b.center[axis],
                    a,
                    b,
                )
                for axis in range(3)
            ]
            terms = []
            for t, ex in enumerate(expansions[0]):
                for u, ey in enumerate(expansions[1]):
                    for v, ez in enumerate(expansions[2]):
                        coefficient = wa * wb * ex * ey * ez
                        if coefficient != 0.0:
                            terms.append((t, u, v, coefficient))
            pairs.append((p, product_center, tuple(terms)))
    return tuple(pairs)


def _coulomb_recursion(exponent, displacement, max_order):
    """Hermite Coulomb integrals, using stable incomplete-gamma Boys functions."""
    squared_distance = sum(x * x for x in displacement)
    argument = exponent * squared_distance
    orders = np.arange(max_order + 1, dtype=float)

    if argument < 1.0e-8:
        boys = np.array([
            sum(
                (-argument) ** k
                / (math.factorial(k) * (2 * n + 2 * k + 1))
                for k in range(6)
            )
            for n in range(max_order + 1)
        ])
    else:
        shape = orders + 0.5
        boys = (
            0.5
            * np.exp(gammaln(shape) - shape * math.log(argument))
            * gammainc(shape, argument)
        )

    @lru_cache(maxsize=None)
    def integral(t, u, v, n):
        if t == 0 and u == 0 and v == 0:
            return float((-2.0 * exponent) ** n * boys[n])
        if t:
            value = displacement[0] * integral(t - 1, u, v, n + 1)
            if t > 1:
                value += (t - 1) * integral(t - 2, u, v, n + 1)
            return value
        if u:
            value = displacement[1] * integral(t, u - 1, v, n + 1)
            if u > 1:
                value += (u - 1) * integral(t, u - 2, v, n + 1)
            return value
        value = displacement[2] * integral(t, u, v - 1, n + 1)
        if v > 1:
            value += (v - 1) * integral(t, u, v - 2, n + 1)
        return value

    return integral


def _nuclear_attraction(pair_expansions, nuclei):
    value = 0.0
    for exponent, product_center, terms in pair_expansions:
        if not terms:
            continue
        max_order = max(t + u + v for t, u, v, _ in terms)
        for charge, nucleus_center in nuclei:
            displacement = tuple(
                product_center[axis] - nucleus_center[axis]
                for axis in range(3)
            )
            recursion = _coulomb_recursion(
                exponent, displacement, max_order
            )
            value -= (
                charge * 2.0 * math.pi / exponent
                * sum(
                    coefficient * recursion(t, u, v, 0)
                    for t, u, v, coefficient in terms
                )
            )
    return value


def _electron_repulsion(pair_ab, pair_cd):
    """Contracted chemists' integral (ab|cd)."""
    value = 0.0
    for p, center_p, terms_ab in pair_ab:
        if not terms_ab:
            continue
        degree_ab = max(t + u + v for t, u, v, _ in terms_ab)
        for q, center_q, terms_cd in pair_cd:
            if not terms_cd:
                continue
            degree_cd = max(t + u + v for t, u, v, _ in terms_cd)
            alpha = p * q / (p + q)
            displacement = tuple(
                center_p[axis] - center_q[axis] for axis in range(3)
            )
            recursion = _coulomb_recursion(
                alpha, displacement, degree_ab + degree_cd
            )

            contracted_sum = 0.0
            for t, u, v, coefficient_ab in terms_ab:
                for tt, uu, vv, coefficient_cd in terms_cd:
                    sign = -1.0 if (tt + uu + vv) % 2 else 1.0
                    contracted_sum += (
                        coefficient_ab * coefficient_cd * sign
                        * recursion(t + tt, u + uu, v + vv, 0)
                    )
            value += (
                2.0 * math.pi**2.5 / (p * q * math.sqrt(p + q))
                * contracted_sum
            )
    return value


def _hf_sto3g_ao_integrals():
    """Construct all integrals directly; no external chemistry package is used."""
    angstrom_to_bohr = 1.8897261246257702
    distance = 0.917 * angstrom_to_bohr
    fluorine = (0.0, 0.0, 0.0)
    hydrogen = (0.0, 0.0, distance)
    nuclei = ((9.0, fluorine), (1.0, hydrogen))

    core_exponents = (166.67913, 30.360812, 8.2168207)
    valence_exponents = (6.4648032, 1.5022812, 0.4885885)
    hydrogen_exponents = (3.42525091, 0.62391373, 0.16885540)

    core_coefficients = (0.15432897, 0.53532814, 0.44463454)
    valence_s_coefficients = (-0.09996723, 0.39951283, 0.70011547)
    valence_p_coefficients = (0.15591627, 0.60768372, 0.39195739)

    aos = [
        _make_ao(
            fluorine, (0, 0, 0), core_exponents,
            core_coefficients, "F 1s"
        ),
        _make_ao(
            fluorine, (0, 0, 0), valence_exponents,
            valence_s_coefficients, "F 2s"
        ),
        _make_ao(
            fluorine, (1, 0, 0), valence_exponents,
            valence_p_coefficients, "F 2px"
        ),
        _make_ao(
            fluorine, (0, 1, 0), valence_exponents,
            valence_p_coefficients, "F 2py"
        ),
        _make_ao(
            fluorine, (0, 0, 1), valence_exponents,
            valence_p_coefficients, "F 2pz"
        ),
        _make_ao(
            hydrogen, (0, 0, 0), hydrogen_exponents,
            core_coefficients, "H 1s"
        ),
    ]

    n = len(aos)
    overlap = np.zeros((n, n))
    one_electron = np.zeros((n, n))
    pair_indices = [(i, j) for i in range(n) for j in range(i + 1)]
    pair_expansions = {}

    for i, j in pair_indices:
        ao_i, ao_j = aos[i], aos[j]
        pairs = _gaussian_pairs(ao_i, ao_j)
        pair_expansions[(i, j)] = pairs

        sij = 0.0
        tij = 0.0
        for a, wa in zip(ao_i.exponents, ao_i.weights):
            for b, wb in zip(ao_j.exponents, ao_j.weights):
                sij += wa * wb * _primitive_overlap(
                    a, ao_i.powers, ao_i.center,
                    b, ao_j.powers, ao_j.center
                )
                tij += wa * wb * _primitive_kinetic(
                    a, ao_i.powers, ao_i.center,
                    b, ao_j.powers, ao_j.center
                )

        hij = tij + _nuclear_attraction(pairs, nuclei)
        overlap[i, j] = overlap[j, i] = sij
        one_electron[i, j] = one_electron[j, i] = hij

    eri = np.zeros((n, n, n, n))
    for pair_number, (i, j) in enumerate(pair_indices):
        for k, l in pair_indices[:pair_number + 1]:
            value = _electron_repulsion(
                pair_expansions[(i, j)], pair_expansions[(k, l)]
            )
            for indices in (
                (i, j, k, l), (j, i, k, l),
                (i, j, l, k), (j, i, l, k),
                (k, l, i, j), (l, k, i, j),
                (k, l, j, i), (l, k, j, i),
            ):
                eri[indices] = value

    if not np.allclose(np.diag(overlap), 1.0, atol=1.0e-11, rtol=0.0):
        raise ArithmeticError("AO normalization check failed.")
    return overlap, one_electron, eri, 9.0 / distance


def _fock_matrix(density, one_electron, eri):
    coulomb = np.einsum("rs,pqrs->pq", density, eri, optimize=True)
    exchange = np.einsum("rs,prqs->pq", density, eri, optimize=True)
    return one_electron + coulomb - 0.5 * exchange


def _diis_extrapolate(fock_history, error_history):
    size = len(fock_history)
    gram = np.array([
        [np.vdot(left, right).real for right in error_history]
        for left in error_history
    ])
    scale = np.max(np.abs(gram))
    if scale < 1.0e-30:
        return fock_history[-1]

    system = np.zeros((size + 1, size + 1))
    system[:size, :size] = gram / scale + 1.0e-14 * np.eye(size)
    system[-1, :size] = -1.0
    system[:size, -1] = -1.0
    rhs = np.zeros(size + 1)
    rhs[-1] = -1.0

    try:
        coefficients = np.linalg.solve(system, rhs)[:size]
    except np.linalg.LinAlgError:
        return fock_history[-1]
    if np.max(np.abs(coefficients)) > 1.0e5:
        return fock_history[-1]
    return sum(
        coefficient * fock
        for coefficient, fock in zip(coefficients, fock_history)
    )


def _restricted_hartree_fock(overlap, one_electron, eri, nuclear_energy):
    """Closed-shell, ten-electron RHF with symmetric orthogonalization and DIIS."""
    n_occupied = 5
    overlap_eigenvalues, overlap_vectors = eigh(overlap)
    if overlap_eigenvalues.min() < 1.0e-10:
        raise ArithmeticError("Linearly dependent AO basis.")

    orthogonalizer = (
        overlap_vectors * overlap_eigenvalues**-0.5
    ) @ overlap_vectors.T

    def canonicalize(fock):
        energies, vectors = eigh(orthogonalizer.T @ fock @ orthogonalizer)
        return energies, orthogonalizer @ vectors

    def make_density(coefficients):
        occupied = coefficients[:, :n_occupied]
        return 2.0 * occupied @ occupied.T

    _, coefficients = canonicalize(one_electron)
    density = make_density(coefficients)
    fock_history, error_history = [], []
    previous_energy = math.inf

    for iteration in range(200):
        fock = _fock_matrix(density, one_electron, eri)
        error = orthogonalizer.T @ (
            fock @ density @ overlap - overlap @ density @ fock
        ) @ orthogonalizer

        fock_history.append(fock.copy())
        error_history.append(error.copy())
        fock_history = fock_history[-8:]
        error_history = error_history[-8:]
        extrapolated = (
            _diis_extrapolate(fock_history, error_history)
            if len(fock_history) >= 2 else fock
        )

        _, coefficients_new = canonicalize(extrapolated)
        density_new = make_density(coefficients_new)
        if iteration < 3:
            density_new = 0.75 * density_new + 0.25 * density

        fock_new = _fock_matrix(density_new, one_electron, eri)
        energy_new = (
            0.5 * np.einsum("pq,pq", density_new, one_electron + fock_new)
            + nuclear_energy
        )
        error_new = orthogonalizer.T @ (
            fock_new @ density_new @ overlap
            - overlap @ density_new @ fock_new
        ) @ orthogonalizer

        if (
            abs(energy_new - previous_energy) < 1.0e-11
            and np.linalg.norm(density_new - density) < 1.0e-9
            and np.linalg.norm(error_new) < 1.0e-9
        ):
            orbital_energies, coefficients = canonicalize(fock_new)
            final_density = make_density(coefficients)
            final_fock = _fock_matrix(final_density, one_electron, eri)
            final_energy = (
                0.5
                * np.einsum(
                    "pq,pq", final_density, one_electron + final_fock
                )
                + nuclear_energy
            )
            return coefficients, orbital_energies, float(final_energy)

        density = density_new
        previous_energy = energy_new

    raise RuntimeError("RHF did not converge in 200 iterations.")


def _construct_cas22(overlap, one_electron, eri, nuclear_energy, coefficients):
    """
    Select the polarized bonding sigma and its antibonding partner.

    HF's highest occupied orbitals are fluorine-centered, nonbonding pi
    orbitals. Blind HOMO/LUMO selection therefore does not describe the H-F
    sigma bond. Among occupied valence sigma MOs, select the one with the
    largest H 1s Lowdin population. The sole STO-3G virtual MO is sigma*.
    Freeze the other four occupied MOs: eight inactive electrons.

    With chemists' ERIs:
      h_eff[p,q] = h[p,q] + sum_i (2(pq|ii) - (pi|iq)),
      E_core = E_nuc + 2 sum_i h[i,i]
               + sum_ij (2(ii|jj) - (ij|ji)).
    The active Hamiltonian retains all active one- and two-electron terms.
    """
    eigenvalues, eigenvectors = eigh(overlap)
    overlap_sqrt = (eigenvectors * np.sqrt(eigenvalues)) @ eigenvectors.T
    lowdin_coefficients = overlap_sqrt @ coefficients

    occupied = list(range(5))
    core_mo = max(
        occupied, key=lambda i: abs(lowdin_coefficients[0, i]) ** 2
    )
    transverse_population = np.sum(
        abs(lowdin_coefficients[[2, 3], :]) ** 2, axis=0
    )
    valence_sigma = [
        i for i in occupied
        if i != core_mo and transverse_population[i] < 1.0e-8
    ]
    if not valence_sigma:
        raise RuntimeError("Could not identify an occupied valence sigma MO.")

    bonding_mo = max(
        valence_sigma, key=lambda i: abs(lowdin_coefficients[5, i]) ** 2
    )
    antibonding_mo = 5
    if transverse_population[antibonding_mo] > 1.0e-8:
        raise RuntimeError("The unique virtual MO was not identified as sigma*.")

    active = [bonding_mo, antibonding_mo]
    frozen = [i for i in occupied if i != bonding_mo]

    h_mo = coefficients.T @ one_electron @ coefficients
    eri_mo = np.einsum(
        "ap,bq,cr,ds,abcd->pqrs",
        coefficients, coefficients, coefficients, coefficients, eri,
        optimize=True,
    )

    core_energy = nuclear_energy + 2.0 * sum(h_mo[i, i] for i in frozen)
    core_energy += sum(
        2.0 * eri_mo[i, i, j, j] - eri_mo[i, j, j, i]
        for i in frozen for j in frozen
    )

    h_active = h_mo[np.ix_(active, active)].copy()
    for p_local, p in enumerate(active):
        for q_local, q in enumerate(active):
            h_active[p_local, q_local] += sum(
                2.0 * eri_mo[p, q, i, i] - eri_mo[p, i, i, q]
                for i in frozen
            )

    eri_active = eri_mo[np.ix_(active, active, active, active)].copy()
    return float(core_energy), h_active, eri_active


def _jw_ladder(mode, n_qubits, creation):
    """Little-endian Jordan-Wigner ladder operator; occupied means |1>."""
    x_label = ["I"] * n_qubits
    y_label = ["I"] * n_qubits
    for lower_mode in range(mode):
        x_label[n_qubits - 1 - lower_mode] = "Z"
        y_label[n_qubits - 1 - lower_mode] = "Z"
    x_label[n_qubits - 1 - mode] = "X"
    y_label[n_qubits - 1 - mode] = "Y"
    return SparsePauliOp.from_list([
        ("".join(x_label), 0.5),
        ("".join(y_label), -0.5j if creation else 0.5j),
    ])


def _real_hermitian_pauli(operator):
    operator = operator.simplify(atol=1.0e-12, rtol=0.0)
    if np.max(np.abs(operator.coeffs.imag)) > 1.0e-10:
        raise ArithmeticError("Expected a Hermitian Pauli operator.")
    return SparsePauliOp(operator.paulis, coeffs=operator.coeffs.real)


def _qubit_hamiltonian(h_active, eri_active):
    """
    Spin-orbital order: [sigma alpha, sigma beta, sigma* alpha, sigma* beta].

    H_active = sum_pq,s h[p,q] a†_(p,s) a_(q,s)
             + 1/2 sum_pqrs,sigma,tau (pq|rs)
               a†_(p,sigma) a†_(r,tau) a_(s,tau) a_(q,sigma).
    """
    n_qubits = 4
    creation = [_jw_ladder(i, n_qubits, True) for i in range(n_qubits)]
    annihilation = [operator.adjoint() for operator in creation]
    operator = SparsePauliOp.from_list([("IIII", 0.0)])

    for p in range(2):
        for q in range(2):
            for spin in range(2):
                operator += h_active[p, q] * (
                    creation[2 * p + spin] @ annihilation[2 * q + spin]
                )

    for p in range(2):
        for q in range(2):
            for r in range(2):
                for s in range(2):
                    coefficient = 0.5 * eri_active[p, q, r, s]
                    if abs(coefficient) < 1.0e-14:
                        continue
                    for sigma in range(2):
                        for tau in range(2):
                            operator += coefficient * (
                                creation[2 * p + sigma]
                                @ creation[2 * r + tau]
                                @ annihilation[2 * s + tau]
                                @ annihilation[2 * q + sigma]
                            )

    return _real_hermitian_pauli(operator), creation, annihilation


def _singlet_ansatz(creation, annihilation):
    """
    Number- and spin-preserving two-parameter ansatz.

    Apply a paired double excitation, then a shared spatial-orbital rotation.
    Every real two-electron/two-orbital singlet is representable: its symmetric
    2x2 geminal matrix can be orthogonally diagonalized, leaving two diagonal
    amplitudes and one orbital-rotation angle. Thus this ansatz can reach the
    exact real CAS(2,2) singlet ground state, not merely a CISD approximation.

    Each generator's Pauli terms commute internally, so one Lie-Trotter step
    implements each exponential exactly, without a Trotter approximation.
    """
    theta_pair = Parameter("theta_pair")
    theta_orbital = Parameter("theta_orbital")

    double_excitation = (
        creation[2] @ creation[3] @ annihilation[1] @ annihilation[0]
    )
    orbital_excitation = (
        creation[2] @ annihilation[0]
        + creation[3] @ annihilation[1]
    )
    generator_pair = _real_hermitian_pauli(
        1.0j * (double_excitation - double_excitation.adjoint())
    )
    generator_orbital = _real_hermitian_pauli(
        1.0j * (orbital_excitation - orbital_excitation.adjoint())
    )

    for generator in (generator_pair, generator_orbital):
        if len(generator.group_commuting(qubit_wise=False)) != 1:
            raise ArithmeticError("Excitation generator terms do not commute.")

    circuit = QuantumCircuit(4)
    circuit.x(0)
    circuit.x(1)
    circuit.append(
        PauliEvolutionGate(
            generator_pair, time=theta_pair, synthesis=LieTrotter(reps=1)
        ),
        range(4),
    )
    circuit.append(
        PauliEvolutionGate(
            generator_orbital, time=theta_orbital,
            synthesis=LieTrotter(reps=1)
        ),
        range(4),
    )
    return circuit, (theta_pair, theta_orbital)


def vqe_hf_sto3g_cas22():
    """
    Return exactly the seven requested outputs.

    Energies are total molecular energies in Hartree, including nuclear
    repulsion and the frozen-occupied electronic constant. The error is the
    absolute error against exact diagonalization of THIS frozen-orbital
    CAS(2,2) Hamiltonian in its two-electron sector. Chemical accuracy means
    error <= 0.0016 Hartree against that reference; it does not establish
    accuracy against experiment, full STO-3G FCI, or the complete-basis limit.
    Orbitals are RHF orbitals, without a subsequent CASSCF orbital optimization.

    This is noiseless, analytic-expectation VQE using Aer statevectors. There
    are zero measurement shots. Measurement-cost metadata records actual
    simulated circuit executions and exact expectations, plus the number of
    qubit-wise commuting measurement groups that sampling would require per
    evaluation. This group count is not a claim of finite-shot precision.

    Circuit resources describe the final bound state-preparation circuit,
    transpiled to {rz, sx, x, cx}, with unrestricted connectivity. They include
    Hartree-Fock preparation, but exclude simulator save instructions,
    measurement rotations, readout, hardware routing, and error correction.
    No qubit tapering is used.

    Basis-set scaling:
      * For K spatial AOs/MOs, conventional dense ERI storage is O(K^4);
        direct RHF Fock construction is O(K^4) per iteration, diagonalization
        O(K^3), and a conventional four-index MO transformation O(K^5).
      * A full Jordan-Wigner treatment uses 2K qubits: 12 for HF/STO-3G.
        Keeping A active spatial orbitals instead uses 2A qubits, here four,
        and O(A^4) generic two-electron/Pauli terms. Straightforward JW
        Pauli-string evolution can require O(A^5) gates per full Trotter step
        before exploiting structure, symmetries, factorization, or compilation.
      * Increasing the AO basis while fixing CAS(2,2) increases classical work
        and changes its integrals, but does not increase its four-qubit count.
        In a larger basis the desired sigma* must be tracked by symmetry and
        orbital character; the LUMO need not be the appropriate antibond.
      * Polarization/diffuse functions improve the polar H-F description.
        Enlarging only the basis while retaining two active orbitals still
        omits substantial external-space correlation. Larger active spaces
        increase quantum resources and generally require richer ansatze.
      * Shot requirements depend on coefficients, state variances, grouping,
        and target precision, not only on term count. Independent Pauli
        measurements have a sufficient allocation scaling as
        (sum_j |c_j|)^2 / epsilon^2, with possible improvements from grouping
        and variance-aware allocation. No such shots are taken here.
    """
    overlap, h_ao, eri_ao, nuclear_energy = _hf_sto3g_ao_integrals()
    coefficients, _, rhf_energy = _restricted_hartree_fock(
        overlap, h_ao, eri_ao, nuclear_energy
    )
    core_energy, h_active, eri_active = _construct_cas22(
        overlap, h_ao, eri_ao, nuclear_energy, coefficients
    )
    active_operator, creation, annihilation = _qubit_hamiltonian(
        h_active, eri_active
    )

    # The molecular CAS Hamiltonian includes the inactive/nuclear constant.
    total_operator = _real_hermitian_pauli(
        active_operator
        + SparsePauliOp.from_list([("IIII", core_energy)])
    )
    active_matrix = np.asarray(active_operator.to_matrix(), dtype=complex)
    total_matrix = np.asarray(total_operator.to_matrix(), dtype=complex)

    # |0011> is the active RHF determinant in Qiskit's little-endian ordering.
    determinant_energy = float(total_matrix[3, 3].real)
    if abs(determinant_energy - rhf_energy) > 2.0e-8:
        raise ArithmeticError(
            "Frozen-core/Jordan-Wigner Hamiltonian failed the RHF energy check."
        )
    if not np.allclose(
        total_matrix, total_matrix.conj().T, atol=1.0e-11, rtol=0.0
    ):
        raise ArithmeticError("The constructed Hamiltonian is not Hermitian.")

    ansatz, parameters = _singlet_ansatz(creation, annihilation)
    basis_gates = ["rz", "sx", "x", "cx"]
    template = transpile(
        ansatz,
        basis_gates=basis_gates,
        optimization_level=3,
        seed_transpiler=17,
    )
    simulator = AerSimulator(
        method="statevector", precision="double", max_parallel_threads=1
    )
    counters = {"executions": 0, "expectations": 0}
    cache = {}

    def evaluate_circuit(unitary_circuit):
        saved = unitary_circuit.copy()
        saved.save_statevector()
        # One deterministic state evolution, with no measurement operations.
        result = simulator.run(saved, shots=1).result()
        if not result.success:
            raise RuntimeError("Aer statevector simulation failed.")
        state = np.asarray(result.get_statevector(saved), dtype=complex)
        counters["executions"] += 1
        energy = float(np.vdot(state, active_matrix @ state).real)
        counters["expectations"] += 1
        return energy, state

    def objective(values):
        key = tuple(float(value) for value in values)
        if key not in cache:
            bound = template.assign_parameters(
                dict(zip(parameters, key)), inplace=False
            )
            cache[key] = evaluate_circuit(bound)
        # Omit the large inactive constant during optimization to improve
        # finite-difference conditioning; restore it in the reported energy.
        return cache[key][0]

    def gradient(values):
        values = np.asarray(values, dtype=float)
        step = 1.0e-5
        result = np.empty(2)
        for index in range(2):
            displacement = np.zeros(2)
            displacement[index] = step
            result[index] = (
                objective(values + displacement)
                - objective(values - displacement)
            ) / (2.0 * step)
        return result

    # No exact eigenvector or reference energy is used to initialize or train
    # the ansatz. Multiple deterministic starts reduce local-stationary risk.
    best_parameters = np.zeros(2)
    best_value = objective(best_parameters)
    for start in ((0.0, 0.0), (0.2, 0.1), (-0.25, 0.25)):
        optimized = minimize(
            objective,
            np.asarray(start, dtype=float),
            method="BFGS",
            jac=gradient,
            options={"gtol": 1.0e-9, "maxiter": 150},
        )
        if np.all(np.isfinite(optimized.x)):
            candidate = objective(optimized.x)
            if candidate < best_value:
                best_value = candidate
                best_parameters = optimized.x.copy()

    polished = minimize(
        objective,
        best_parameters,
        method="Powell",
        options={
            "xtol": 1.0e-10,
            "ftol": 1.0e-13,
            "maxiter": 200,
            "maxfev": 2000,
        },
    )
    if np.all(np.isfinite(polished.x)):
        candidate = objective(polished.x)
        if candidate < best_value:
            best_value = candidate
            best_parameters = polished.x.copy()

    final_circuit = transpile(
        template.assign_parameters(
            dict(zip(parameters, map(float, best_parameters))), inplace=False
        ),
        basis_gates=basis_gates,
        optimization_level=3,
        seed_transpiler=17,
    )
    final_active_energy, final_state = evaluate_circuit(final_circuit)
    ground_state_energy = core_energy + final_active_energy

    two_electron_indices = [
        index for index in range(16) if index.bit_count() == 2
    ]
    particle_probability = float(
        np.sum(abs(final_state[two_electron_indices]) ** 2)
    )

    singlet_basis = np.zeros((16, 3), dtype=complex)
    singlet_basis[3, 0] = 1.0
    singlet_basis[9, 1] = 1.0 / math.sqrt(2.0)
    singlet_basis[6, 1] = -1.0 / math.sqrt(2.0)
    singlet_basis[12, 2] = 1.0
    singlet_probability = float(
        np.sum(abs(singlet_basis.conj().T @ final_state) ** 2)
    )
    if (
        abs(particle_probability - 1.0) > 1.0e-9
        or abs(singlet_probability - 1.0) > 1.0e-9
    ):
        raise ArithmeticError("The VQE circuit leaked from the two-electron singlet.")

    # Reference includes all six two-electron determinants, including triplets;
    # diagonalizing the unrestricted 16-dimensional Fock space would compare
    # against potentially incorrect electron-number sectors.
    reference_matrix = total_matrix[
        np.ix_(two_electron_indices, two_electron_indices)
    ]
    reference_energy = float(np.linalg.eigvalsh(reference_matrix)[0])
    energy_error = abs(ground_state_energy - reference_energy)

    nonidentity_terms = [
        (label, complex(coefficient))
        for label, coefficient in total_operator.to_list()
        if label != "IIII" and abs(coefficient) > 1.0e-12
    ]
    measurement_groups = (
        len(
            SparsePauliOp.from_list(nonidentity_terms).group_commuting(
                qubit_wise=True
            )
        )
        if nonidentity_terms else 0
    )

    return {
        "ground_state_energy_estimate": float(ground_state_energy),
        "energy_error_against_reference": float(energy_error),
        "chemical_accuracy_achievement": bool(energy_error <= 1.6e-3),
        "measurement_cost": {
            "estimator": "noiseless Aer statevector; exact expectations",
            "shots": 0,
            "statevector_circuit_executions": int(counters["executions"]),
            "exact_energy_evaluations": int(counters["expectations"]),
            "nonidentity_pauli_terms": len(nonidentity_terms),
            "qubit_wise_commuting_groups_if_sampled": int(measurement_groups),
        },
        "qubit_count": int(final_circuit.num_qubits),
        "circuit_depth": int(final_circuit.depth()),
        "gate_count": int(sum(final_circuit.count_ops().values())),
    }


if __name__ == "__main__":
    print(json.dumps(vqe_hf_sto3g_cas22(), indent=2))

