def _singlet_ansatz(creation, annihilation):
    """
    Number- and spin-preserving two-parameter ansatz.

    Apply a paired double excitation, then a shared spatial-orbital rotation.
    Every real two-electron/two-orbital singlet is representable: its symmetric
    2x2 geminal matrix can be orthogonally diagonalized, leaving two diagonal
    amplitudes and one orbital-rotation angle. Thus this ansatz can reach the
    exact real CAS(2,2) singlet ground state, not merely a CISD approximation.

    Each generator's Pauli terms commute internally, so one Lie-Trotter step
    implements each exponential exactly, without a Trotter approximation.
    """
    theta_pair = Parameter("theta_pair")
    theta_orbital = Parameter("theta_orbital")

    double_excitation = (
        creation[2] @ creation[3] @ annihilation[1] @ annihilation[0]
    )
    orbital_excitation = (
        creation[2] @ annihilation[0]
        + creation[3] @ annihilation[1]
    )
    generator_pair = _real_hermitian_pauli(
        1.0j * (double_excitation - double_excitation.adjoint())
    )
    generator_orbital = _real_hermitian_pauli(
        1.0j * (orbital_excitation - orbital_excitation.adjoint())
    )

    for generator in (generator_pair, generator_orbital):
        if len(generator.group_commuting(qubit_wise=False)) != 1:
            raise ArithmeticError("Excitation generator terms do not commute.")

    circuit = QuantumCircuit(4)
    circuit.x(0)
    circuit.x(1)
    circuit.append(
        PauliEvolutionGate(
            generator_pair, time=theta_pair, synthesis=LieTrotter(reps=1)
        ),
        range(4),
    )
    circuit.append(
        PauliEvolutionGate(
            generator_orbital, time=theta_orbital,
            synthesis=LieTrotter(reps=1)
        ),
        range(4),
    )
    return circuit, (theta_pair, theta_orbital)


